"""Printed 9–11 gas transport. Numerical/source statements are retained."""
def p(en,ur,ps):return {'text':en,'urdu':ur,'pashto':ps}
TRANSPORT=[p('Like other materials, respiratory gases are also transported in various regions of the body by means of blood.','دیگر مادوں کی طرح تنفسی گیسیں بھی خون کے ذریعے جسم کے مختلف حصوں میں پہنچائی جاتی ہیں۔','د نورو موادو په څېر تنفسي ګازونه هم د وینې په وسیله د بدن بېلابېلو برخو ته لېږدول کېږي.'),p('The blood transports oxygen from the lungs to different tissues and carbon dioxides from tissues to the lungs.','خون آکسیجن کو پھیپھڑوں سے مختلف بافتوں تک اور کاربن ڈائی آکسائیڈ کو بافتوں سے پھیپھڑوں تک پہنچاتا ہے۔','وینه اکسیجن له سږو څخه بېلابېلو نسجونو ته او کاربن ډای اکسایډ له نسجونو څخه سږو ته لېږدوي.')]
OXYGEN=[
p('Approximately 97% of oxygen is carried by the red blood cells as oxyhaemoglobin, while 3% is transported as dissolved oxygen in the plasma.','تقریباً 97% آکسیجن سرخ خلیے آکسی ہیموگلوبن کی صورت میں لے جاتے ہیں، جبکہ 3% پلازما میں حل شدہ آکسیجن کے طور پر منتقل ہوتی ہے۔','نږدې 97% اکسیجن د وینې سرې حجرې د اکسي هیموګلوبین په بڼه لېږدوي، خو 3% په پلازما کې د حل شوي اکسیجن په بڼه لېږدول کېږي.'),
p('At high partial pressure of oxygen, oxygen binds with haemoglobin.','آکسیجن کے زیادہ جزوی دباؤ پر آکسیجن ہیموگلوبن سے جڑتی ہے۔','د اکسیجن په لوړ جزوي فشار کې اکسیجن له هیموګلوبین سره تړل کېږي.'),
p('This binding is a reversible reaction that occurs in the alveoli of the lungs in the presence of enzyme carbonic anhydrase.','یہ اتصال قابلِ واپسی تعامل ہے جو پھیپھڑوں کے ہوائی تھیلوں میں کاربونک اینہائیڈریز خامرے کی موجودگی میں ہوتا ہے۔','دا تړل کېدل بېرته ګرځېدونکی تعامل دی چې د سږو په الویولونو کې د کاربونیک انهایدرېز انزایم په شتون کې ترسره کېږي.'),
p('Each molecule of haemoglobin can bind with four molecules of oxygen to form oxyhaemoglobin.','ہیموگلوبن کا ہر سالمہ آکسیجن کے چار سالموں سے جڑ کر آکسی ہیموگلوبن بنا سکتا ہے۔','د هیموګلوبین هر مالیکول د اکسیجن له څلورو مالیکولونو سره تړل کېدای شي او اکسي هیموګلوبین جوړوي.'),
p('Hb + 4O₂ → Hb4O₂ (carbonic anhydrase written above the arrow in the source).','Hb + 4O₂ → Hb4O₂؛ اصل شکل میں تیر کے اوپر کاربونک اینہائیڈریز لکھا ہے۔','Hb + 4O₂ → Hb4O₂؛ په اصلي شکل کې د غشي پر سر کاربونیک انهایدرېز لیکل شوی دی.'),
p('The ability of haemoglobin to bind with oxygen is called oxygen carrying capacity of blood.','ہیموگلوبن کی آکسیجن سے جڑنے کی صلاحیت خون کی آکسیجن لے جانے کی گنجائش کہلاتی ہے۔','له اکسیجن سره د هیموګلوبین د تړل کېدو وړتیا د وینې د اکسیجن د لېږد ظرفیت بلل کېږي.'),
p('The oxygen carrying capacity of blood is directly proportional to the partial pressure of oxygen (PO₂).','خون کی آکسیجن لے جانے کی گنجائش آکسیجن کے جزوی دباؤ (PO₂) کے راست متناسب ہوتی ہے۔','د وینې د اکسیجن د لېږد ظرفیت د اکسیجن له جزوي فشار (PO₂) سره مستقیم تناسب لري.'),
p('Maximum oxygen carrying capacity of arterial blood is 20 ml/100 ml of blood (100% saturated) which is achieved at 100 mmHg PO₂.','شریانی خون کی زیادہ سے زیادہ آکسیجن لے جانے کی گنجائش ہر 100 ملی لیٹر خون میں 20 ملی لیٹر ہے؛ یہ 100% اشباع 100 mmHg PO₂ پر حاصل ہوتا ہے۔','د شریاني وینې د اکسیجن د لېږد اعظمي ظرفیت په هر 100 ملي لیټره وینه کې 20 ملي لیټره دی؛ دا 100% اشباع په 100 mmHg PO₂ کې ترلاسه کېږي.'),
p('This is because the amount of haemoglobin is 15 gms/100 ml of blood.','اس کی وجہ یہ ہے کہ ہر 100 ملی لیٹر خون میں ہیموگلوبن کی مقدار 15 گرام ہوتی ہے۔','دا ځکه چې په هر 100 ملي لیټره وینه کې د هیموګلوبین اندازه 15 ګرامه ده.'),
p('Since 1gm Hb can combine with 1.34 ml of O₂, therefore 100 ml blood combines with 20 ml O₂ (100% saturated).','چونکہ 1 گرام Hb، 1.34 ملی لیٹر O₂ سے جڑ سکتا ہے، اس لیے 100 ملی لیٹر خون 20 ملی لیٹر O₂ سے جڑتا ہے، یعنی 100% اشباع ہوتا ہے۔','څرنګه چې 1 ګرام Hb له 1.34 ملي لیټره O₂ سره تړل کېدای شي، نو 100 ملي لیټره وینه له 20 ملي لیټره O₂ سره تړل کېږي، یعنې 100% اشباع کېږي.'),
p('Normally each 100 ml of arterial blood contains 19.4 ml O₂ (i.e. it is 97% saturated; PO₂ is 95 mmHg), while 100 ml of venous blood contains 14.4 ml O₂ (i.e. it is 75% saturated; PO₂ is 40 mmHg).','عموماً ہر 100 ملی لیٹر شریانی خون میں 19.4 ملی لیٹر O₂ ہوتی ہے؛ یعنی 97% اشباع اور PO₂، 95 mmHg ہے؛ جبکہ 100 ملی لیٹر وریدی خون میں 14.4 ملی لیٹر O₂ ہوتی ہے؛ یعنی 75% اشباع اور PO₂، 40 mmHg ہے۔','په عادي ډول هر 100 ملي لیټره شریاني وینه 19.4 ملي لیټره O₂ لري؛ یعنې 97% اشباع او PO₂ یې 95 mmHg دی؛ خو 100 ملي لیټره وریدي وینه 14.4 ملي لیټره O₂ لري؛ یعنې 75% اشباع او PO₂ یې 40 mmHg دی.'),
p('Thus, 5 ml of O₂ is released to the tissues by each 100 ml blood.','یوں ہر 100 ملی لیٹر خون بافتوں کو 5 ملی لیٹر O₂ دیتا ہے۔','نو هر 100 ملي لیټره وینه نسجونو ته 5 ملي لیټره O₂ خوشې کوي.'),
p('During exercise, the need of oxygen is greatly increased in the tissues so more oxygen is released by the arterial blood to the tissues.','ورزش کے دوران بافتوں میں آکسیجن کی ضرورت بہت بڑھ جاتی ہے، اس لیے شریانی خون بافتوں کو زیادہ آکسیجن دیتا ہے۔','د تمرین پر مهال په نسجونو کې د اکسیجن اړتیا ډېره زیاتېږي، نو شریاني وینه نسجونو ته ډېر اکسیجن خوشې کوي.'),
p('The venous blood that leaves an active tissue has only 4.4 ml O₂ per 100 ml of blood (20% saturated; PO₂ is 18 mmHg).','فعال بافت سے نکلنے والے وریدی خون کے ہر 100 ملی لیٹر میں صرف 4.4 ملی لیٹر O₂ ہوتی ہے؛ اشباع 20% اور PO₂، 18 mmHg ہے۔','له فعال نسج څخه وتونکې وریدي وینه په هر 100 ملي لیټره کې یوازې 4.4 ملي لیټره O₂ لري؛ 20% اشباع او PO₂ یې 18 mmHg دی.'),
p('Compared to carbon dioxide, oxygen is relatively insoluble in the blood, therefore a small amount of O₂ is transported in dissolved state in the plasma.','کاربن ڈائی آکسائیڈ کے مقابلے میں آکسیجن خون میں نسبتاً کم حل ہوتی ہے، اس لیے O₂ کی تھوڑی مقدار پلازما میں حل شدہ حالت میں منتقل ہوتی ہے۔','د کاربن ډای اکسایډ په پرتله اکسیجن په وینه کې نسبتاً لږ حل کېږي، نو د O₂ لږه اندازه په پلازما کې په حل شوي حالت لېږدول کېږي.'),
p('Normally each 100 ml blood contain 0.29 ml O₂ (PO₂ is 95 mmHg) and this capacity may increase up to 0.3 ml/100 ml blood at 100 mmHg PO₂.','عموماً ہر 100 ملی لیٹر خون میں 0.29 ملی لیٹر O₂ ہوتی ہے، جب PO₂، 95 mmHg ہو؛ 100 mmHg PO₂ پر یہ گنجائش ہر 100 ملی لیٹر خون میں 0.3 ملی لیٹر تک بڑھ سکتی ہے۔','په عادي ډول هر 100 ملي لیټره وینه 0.29 ملي لیټره O₂ لري چې PO₂ یې 95 mmHg دی؛ په 100 mmHg PO₂ کې دا ظرفیت په هر 100 ملي لیټره وینه کې تر 0.3 ملي لیټره زیاتېدای شي.'),
p('While the 100 ml of venous blood has 0.12 ml of dissolved O₂ (PO₂ is 40 mmHg).','جبکہ 100 ملی لیٹر وریدی خون میں 0.12 ملی لیٹر حل شدہ O₂ ہوتی ہے؛ PO₂، 40 mmHg ہے۔','خو 100 ملي لیټره وریدي وینه 0.12 ملي لیټره حل شوی O₂ لري؛ PO₂ یې 40 mmHg دی.'),
p('Thus, 0.17 ml of O₂ is transported by each 100 ml blood through the tissues per cycle in the dissolved state.','یوں ہر چکر میں ہر 100 ملی لیٹر خون بافتوں کے ذریعے 0.17 ملی لیٹر O₂ حل شدہ حالت میں منتقل کرتا ہے۔','نو په هره دوره کې هر 100 ملي لیټره وینه د نسجونو له لارې 0.17 ملي لیټره O₂ په حل شوي حالت لېږدوي.')]
REVISIONS=[('14.5 MECHANISM OF TRANSPORT OF GASES','گیسوں کی منتقلی کا طریقہ','د ګازونو د لېږد میکانیزم',TRANSPORT,[9]),('14.5.1 Transport of oxygen in blood:','خون میں آکسیجن کی منتقلی','په وینه کې د اکسیجن لېږد',OXYGEN,[9,10,11])]
